export type CategorySummary = {
  name: string;
  description: string;
  count: number;
};

// Derive categories from products
const categoryMap = new Map<string, number>();
products.forEach((p) => {
  categoryMap.set(p.category, (categoryMap.get(p.category) ?? 0) + 1);
});

const categoryDescriptions: Record<string, string> = {
  "Angle Bars": "Equal and unequal angle bars",
  "Channel Bars": "C-channel structural steel",
  "Deformed Bars": "Reinforcing steel bars (rebar)",
  "Flat Bars": "Flat steel bars",
  "Pipes": "Galvanized, seamless, and spiral welded pipes",
  "Tubings": "Lightweight steel tubes",
  "Plates": "Mild steel and checkered plates",
  "Wide Flanges": "Wide flange I-beams",
  "Purlins": "C-purlins for roofing",
  "Coil": "Steel coils",
  "Sheet Piles": "Steel sheet piles",
  "T-Beams": "T-shaped structural beams",
  "Other Services": "Cutting, welding, and other services",
};

export const categories: CategorySummary[] = Array.from(categoryMap.entries()).map(
  ([name, count]) => ({
    name,
    description: categoryDescriptions[name] ?? "",
    count,
  })
);
